-- Daily challenges for 2026-10-24: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-10-24. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('feeling-at-home-in-your-body', 'Feeling at Home in Your Body', 'For anyone who feels at odds with their body or only notices it when something hurts. Each day is one small way to notice, thank and care for it, so your body feels more like a friendly place to live.', 'Body', 365, array['Body', 'Self-Compassion', 'Self-Esteem']::text[], 1, '2026-10-24T17:00:00+00:00'::timestamptz),
  ('staying-curious', 'Staying Curious', 'For anyone whose days have started to feel flat or stuck on autopilot. Each day is one small way to wonder, ask and notice, so ordinary life and the people in it feel a little more interesting.', 'Thinking', 365, array['Mindfulness', 'Relationships', 'Motivation']::text[], 1, '2026-10-24T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('feeling-at-home-in-your-body', 'staying-curious');

